"""Binary search in an ordered list
    Complexity: O(log n)

    Args:
        ordered_list (list): An ordered list.
        item (int): The item to search.

    Returns:
        bool: Boolean with the answer of the search.

    Examples:
        >>> alist = [0, 1, 2, 8, 13, 17, 19, 32, 42]
        >>> sequential_search(alist, 3)
        False
        >>> sequential_search(alist, 13)
        True
    """
def ordered_binary_search(ordered_list: Any, item: Any) -> object {
    first = 0;
    last = len(ordered_list) - 1;
    found = False;
    while ((first <= last) and not found) {
        midpoint = (first + last) // 2;
        if (ordered_list[midpoint] == item) {
            found = True;
        } elif (item < ordered_list[midpoint]) {
            last = midpoint - 1;
        } else {
            first = midpoint + 1;
        }
        return found;
    }
}

"""Prettifies logger messages by breaking them up into multi lines"""
def prettify_logger_message(msg: Any) -> object {
    import from textwrap { wrap }
    linewidth = 75 - 13;
    indent = "\n" + (" " * 13);
    temp = wrap(msg, width=linewidth);
    return indent.join(temp);
}

"""Suffix strip

    >>> sstrip('foo.oof', '.oof')
    'foo'
    >>> sstrip('baroof', '.oof')
    'baroof'
    """
def sstrip(s: Any, suffix: Any) -> object {
    i = -len(suffix);
    if (s[i:] == suffix) {
        return s[:i];
    }
    return s;
}

