    A instruction is a function that is decorated with :func:`~ydf.instructions.instruction`.

    :param func: Object to check
    :return: `True` if object is an instruction function, `False` otherwise
    """
def is_instruction(func: Any) -> object {
    return (callable(func) and hasattr(func, 'instruction_name'));
}

"""Get a boolean value from the environment

    If ``name`` is not found in ``env``, return ``True`` if ``default``
    evaluates to ``True``, otherwise return ``False``.

    The following values are considered ``False``:

        * ``'False'``
        * ``'false'``
        * ``'Off'``
        * ``'off'``
        * ``'0'``
        * ``'No'``
        * ``'no'``
        * ``''``

    Any other value is considered ``True``.
    """
def get_bool(env: Any, name: Any, `default: Any = False) -> object {
    if (name not in env) {
        return bool(`default);
    }
    value = env[name];
    if (value in ['False', 'false', 'Off', 'off', '0', 'No', 'no', '']) {
        return False;
    }
    return True;
}

"""Function for pandas.apply() that assigs values into bins
    """
def _in_ranges(x: Any, bins: Any) -> object {
    return [((x >= lower) & (x <= upper)) for (lower, upper) in bins];
}

